#!/usr/bin/env python3
"""Static contracts for the security-header artifacts of every app.

These files are the ones a host actually obeys, and nothing else in the pipeline
reads them:

  * `apps/web/public/_headers`    → rewritten in place by
                                    `apps/web/scripts/finalize-csp.ts`
  * `apps/jbrowse/public/_headers`→ rewritten in place by its own injector
  * `apps/admin/public/_headers`  → generated by the admin Vite plugin

The checks fall into three groups.

**Presence and finalization.** Each artifact exists, and the portal/JBrowse CSP
carries the origins the build was configured with — not the conservative
same-origin default that ships in source. A build that never ran its finalizer
would otherwise publish a header policy that silently blocks the API.

**CSP agreement.** The site-wide header is the *union* of every page's inline
hashes, so the correct relation is a subset, not equality:

    page <meta> script-src hashes  ⊆  _headers script-src hashes

Equality would be wrong: `renderRedirectTemplate` emits no `<meta>` policy, so
those pages contribute hashes to the header that no page's meta contains.

The remaining directives must be byte-identical between the two, because the
browser intersects them. That is the failure this catches: a meta policy missing
`frame-ancestors` silently widens nothing (the header still applies), but a meta
policy that *omits* an origin the header allows narrows the intersection and
breaks the page in a way that reads as "the API is down".

**Registry rules.** No placeholder origin, no sentinel token, and no inline
script permission left in `script-src`.

Usage: python3 scripts/check_artifact_headers.py [--json] [--require-dual]

`--require-dual` is the strict mode for the caller that runs *after* the dual-site
build: it additionally requires both variant trees to be present instead of
validating whichever trees exist. Without it the gate is order-independent, which
is what lets `verify-frontend-artifacts.sh` run it after its single-tree build.
"""

from __future__ import annotations

import argparse
import html
import json
import re
import sys
from dataclasses import dataclass, field
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

# Directives the page policy and the site policy must agree on. script-src is
# excluded because the header is the union; connect-src and frame-src are
# excluded because a page may legitimately narrow them (the minimal deployment
# omits the JBrowse frame origin entirely).
MUST_AGREE = (
    "default-src",
    "style-src",
    "img-src",
    "font-src",
    "base-uri",
    "form-action",
    "frame-ancestors",
    "object-src",
    "worker-src",
)

# Tokens that must never survive into a published header file.
PLACEHOLDER_RE = re.compile(
    r"example\.com|localhost|127\.0\.0\.1|CHANGE_ME|change-me|__[A-Z_]+__|%[A-Z_]+%",
    re.I,
)

# Build-time variable names that must never appear in a published artifact.
#
# The build rewrites the origin-bearing CSP directives from these variables, so
# a literal name in the emitted file means one of two things and nothing can
# tell them apart from the bytes alone: the substitution silently did not run,
# or someone wrote the variable name into a comment. The second case is not
# harmless either — it breaks the artifact contract check in
# `.github/workflows/baseline-validation.yml`, which greps the built tree for
# exactly these names, and a gate that has to be narrowed to accommodate a
# comment is a gate that has stopped working.
#
# It happened once: `apps/web/public/_headers` and `apps/admin/public/_headers`
# documented the variables in comments, which `_headers` copies verbatim into
# `dist/`, and the contract step failed with no build error to explain it. The
# operator-facing documentation for these variables lives in
# `docs/ops/production-build.md` instead.
BUILD_VARIABLE_RE = re.compile(
    r"\bVITE_(?:API_BASE_URL|JBROWSE_BASE_URL|JBROWSE_DATA_URL)\b"
    r"|\bSOYMUTDB_(?:PORTAL_ORIGIN|ADMIN_ORIGIN)\b"
)

HEADERS_CSP_RE = re.compile(r"^\s*Content-Security-Policy:\s*(\S.*)$", re.M)
META_CSP_RE = re.compile(
    r'<meta\s+http-equiv="Content-Security-Policy"\s+content="([^"]*)"', re.S | re.I
)
SCRIPT_HASH_RE = re.compile(r"^sha256-[A-Za-z0-9+/]+=*$")

# `apps/web/dist/{external,internal}` plus the single-tree apps. A missing tree
# is a finding only for the portal variants: the others are built by their own
# image and may legitimately be absent in a frontend-only run.
PORTAL_VARIANTS = ("external", "internal")
OTHER_APPS = ("apps/admin", "apps/jbrowse")

# Origin each artifact must carry once finalized, expressed as the env var whose
# value the build was given. Kept as names so this file does not embed a
# placeholder-looking literal of its own.
REQUIRED_ORIGIN_ENV = {
    "apps/web": "VITE_API_BASE_URL",
    "apps/jbrowse": "VITE_API_BASE_URL",
}


@dataclass
class Report:
    findings: list[tuple[str, str]] = field(default_factory=list)
    checked: list[str] = field(default_factory=list)

    def fail(self, where: str, message: str) -> None:
        self.findings.append((str(where), message))


def parse_csp(policy: str) -> dict[str, list[str]]:
    out: dict[str, list[str]] = {}
    for clause in policy.split(";"):
        parts = clause.split()
        if parts:
            out[parts[0].lower()] = parts[1:]
    return out


def script_hashes(policy: str) -> set[str]:
    return {t for t in parse_csp(policy).get("script-src", []) if t.startswith("sha256-")}


def script_tokens(policy: str) -> list[str]:
    return [t for t in parse_csp(policy).get("script-src", [])]


def read_headers_csp(path: Path, report: Report) -> str | None:
    text = path.read_text(encoding="utf-8")
    match = HEADERS_CSP_RE.search(text)
    if not match:
        report.fail(path, "has no Content-Security-Policy line")
        return None
    return match.group(1).strip()


def check_no_placeholders(path: Path, report: Report) -> None:
    text = path.read_text(encoding="utf-8")
    for found in sorted({m.group(0) for m in PLACEHOLDER_RE.finditer(text)}):
        report.fail(path, f"contains a placeholder/sentinel token: {found!r}")
    for found in sorted({m.group(0) for m in BUILD_VARIABLE_RE.finditer(text)}):
        report.fail(
            path,
            f"names the build variable {found!r}; a published artifact must carry "
            "the substituted origin, and the artifact contract greps for these "
            "names. Document them in docs/ops/production-build.md instead.",
        )


def check_portal_variant(artifact: Path, report: Report) -> None:
    headers = artifact / "_headers"
    if not headers.is_file():
        report.fail(headers, "missing: the Pages deployment would serve no security headers")
        return
    report.checked.append(str(headers))
    check_no_placeholders(headers, report)

    site_csp = read_headers_csp(headers, report)
    if site_csp is None:
        return
    site_map = parse_csp(site_csp)

    # Finalization proof: a real origin, and no inline-script permission.
    if "'unsafe-inline'" in site_map.get("script-src", []):
        report.fail(headers, "script-src still allows 'unsafe-inline' (finalizer did not run?)")
    # A document set with no inline scripts legitimately finalizes to an empty
    # hash union, so "no hash" is not evidence either way. What *is* checkable is
    # that the header policy came from the finalizer rather than from the
    # pre-finalization source file: the finalizer drops 'unsafe-inline' from
    # script-src, which the source `_headers` carries. The origin check below is
    # the second half of the same proof.
    connect = site_map.get("connect-src", [])
    if not [t for t in connect if t.startswith("http")]:
        report.fail(
            headers,
            f"connect-src has no absolute origin ({connect}) — this is the "
            "conservative pre-finalization default, so every cross-origin API call "
            "would be blocked",
        )

    site_hashes = script_hashes(site_csp)
    pages = sorted(artifact.rglob("*.html"))
    if not pages:
        report.fail(artifact, "contains no HTML documents to check against the header policy")
        return

    for page in pages:
        match = META_CSP_RE.search(page.read_text(encoding="utf-8"))
        if not match:
            continue
        policy = html.unescape(match.group(1))
        page_map = parse_csp(policy)
        page_hashes = script_hashes(policy)

        if "'unsafe-inline'" in page_map.get("script-src", []):
            report.fail(page, "meta script-src still allows 'unsafe-inline'")
        leaked = page_hashes - site_hashes
        if leaked:
            report.fail(
                page,
                f"meta script-src hashes absent from the site-wide header: {sorted(leaked)} "
                "— the header would block these scripts",
            )
        for directive in MUST_AGREE:
            if page_map.get(directive) != site_map.get(directive):
                report.fail(
                    page,
                    f"meta {directive}={page_map.get(directive)} does not match the "
                    f"header {directive}={site_map.get(directive)}; the browser "
                    "intersects the two, so the narrower one wins",
                )


def check_other_app(app: Path, report: Report) -> None:
    dist = app / "dist"
    headers = dist / "_headers"
    if not headers.is_file():
        # Not every app is built in every run; the source file is the contract.
        source = app / "public" / "_headers"
        if not source.is_file():
            report.fail(source, "missing source _headers")
            return
        check_no_placeholders(source, report)
        report.checked.append(str(source))
        return
    report.checked.append(str(headers))
    check_no_placeholders(headers, report)
    if read_headers_csp(headers, report) is None:
        return


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--json", action="store_true")
    parser.add_argument(
        "--require-dual",
        action="store_true",
        help="require both portal variants to exist (run after the dual-site build)",
    )
    args = parser.parse_args()

    report = Report()

    if args.require_dual:
        for variant in PORTAL_VARIANTS:
            headers = ROOT / "apps" / "web" / "dist" / variant / "_headers"
            if not headers.is_file():
                report.fail(
                    headers,
                    "missing: --require-dual was requested, so both variants must exist. "
                    "A single-tree `pnpm build` replaces dist/ and removes them, so the "
                    "dual-site build has to run last "
                    "(docs/superpowers/plans/2026-09-15-portal-security-ux-perf-optimization.md "
                    "§2.3).",
                )

    # Validate every portal tree that exists, and require at least one.
    #
    # The dual-variant *presence* contract is asserted by
    # scripts/test_site_artifact_isolation.py, not here, and that split is
    # deliberate: `verify-frontend-artifacts.sh` runs a single-tree build, and its
    # root `dist/` replaces the variant directories. A gate that demanded both
    # variants would be red on every single-tree run and could only be made green
    # by reordering the whole frontend job. This gate answers "is the tree that
    # exists finalized and coherent", which is order-independent.
    portal_trees = [ROOT / "apps" / "web" / "dist" / v for v in PORTAL_VARIANTS]
    single = ROOT / "apps" / "web" / "dist"
    if single.is_dir() and (single / "index.html").is_file():
        portal_trees.append(single)
    present = [tree for tree in portal_trees if (tree / "_headers").is_file()]

    if not present:
        report.fail(
            ROOT / "apps" / "web" / "dist",
            "no finalized portal tree found (neither dist/{external,internal} nor a "
            "single-tree dist) — build the portal before running this gate",
        )
    for tree in present:
        check_portal_variant(tree, report)

    for app in OTHER_APPS:
        check_other_app(ROOT / app, report)

    if args.json:
        print(json.dumps(
            {
                "checked": report.checked,
                "findings": [{"path": p, "message": m} for p, m in report.findings],
            },
            indent=2,
        ))
    else:
        print(f"artifact headers: {len(report.checked)} file(s) checked")
        for where, message in report.findings:
            print(f"  FAIL  {where}: {message}")

    if report.findings:
        print(f"artifact headers: FAILED — {len(report.findings)} finding(s)")
        return 1
    print("artifact headers: OK")
    return 0


if __name__ == "__main__":
    sys.exit(main())
